<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('grouping_dashboard') }}
          <q-spinner-ios v-if="dashboard_grouping_loading" size="16px" color="primary" class="q-ml-sm" />
        </span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_clickhouse_popup"
          :settings="{}"
          :settingType="grouping_dashboard_setting"
          :appKey="CONSTANTS.grouping_dashboard"
          :onConfirm="handleClickhouseSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[grouping_dashboard_setting]"
          :disable="loading"
          @update:model-value="saveClickhouse"
        />
      </div>
    </div>

    <template v-if="user_settings[grouping_dashboard_setting]">
      <div class="settings-toggle-item">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">
            {{ $t('reporting_engine') }}
            <q-spinner-ios v-if="loading" size="16px" color="primary" class="q-ml-sm" />
          </span>
        </div>
        <div class="settings-toggle-actions">
          <f-toggle size="xs"
            v-model="user_settings[warehouse_reporting_engine_setting]"
            :disable="loading"
            @update:model-value="(val: any) => { setReportingEngineSetting(warehouse_reporting_engine_setting, val); }"
          />
        </div>
      </div>

      <div class="settings-toggle-item" v-if="user_settings[grouping_dashboard_setting]">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">
            {{ $t('supplier_statistics_setting') }}
            <q-spinner-ios v-if="loading" size="16px" color="primary" class="q-ml-sm" />
          </span>
        </div>
        <div class="settings-toggle-actions">
          <f-toggle size="xs"
            v-model="user_settings[supplier_statistics_setting]"
            :disable="loading"
            @update:model-value="(val) => { updateSupplierStatisticsSetting(supplier_statistics_setting, val) }"
          />
        </div>
      </div>

      <template v-if="user_settings[grouping_dashboard_setting] && user_settings[warehouse_reporting_engine_setting]">
        <div class="settings-db-credentials">
          <div class="settings-db-row">
            <q-input
              outlined
              dense
              class="s-field back-white"
              v-model="warehouse_user_settings[warehouse_username_setting]"
              :label="$t('username')"
              :readonly="true"
            >
              <template v-slot:append>
                <q-spinner-ios v-if="loading" size="16px" color="primary" />
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(warehouse_user_settings[warehouse_username_setting])"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </template>
            </q-input>
            <q-input
              outlined
              dense
              class="s-field back-white"
              v-model="warehouse_user_settings[warehouse_password_setting]"
              :label="$t('password')"
              :readonly="true"
            >
              <template v-slot:append>
                <q-spinner-ios v-if="loading" size="16px" color="primary" />
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(warehouse_user_settings[warehouse_password_setting])"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>

          <div class="settings-db-row">
            <q-input
              outlined
              dense
              class="s-field back-white"
              v-model="warehouse_user_settings[warehouse_database_setting]"
              :label="$t('Database')"
              :readonly="true"
            >
              <template v-slot:append>
                <q-spinner-ios v-if="loading" size="16px" color="primary" />
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(warehouse_user_settings[warehouse_database_setting])"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </template>
            </q-input>
            <q-input
              outlined
              dense
              class="s-field back-white"
              v-model="warehouse_user_settings[warehouse_host_setting]"
              :label="$t('host')"
              :readonly="true"
            >
              <template v-slot:append>
                <q-spinner-ios v-if="loading" size="16px" color="primary" />
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(warehouse_user_settings[warehouse_host_setting])"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </template>
            </q-input>
            <q-input
              outlined
              dense
              class="s-field back-white"
              style="max-width: 120px;"
              v-model="warehouse_user_settings[warehouse_port_setting]"
              :label="$t('port')"
              :readonly="true"
            >
              <template v-slot:append>
                <q-spinner-ios v-if="loading" size="16px" color="primary" />
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(warehouse_user_settings[warehouse_port_setting])"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>

          <div class="settings-db-tables">
            <span class="settings-db-tables-label">{{ $t('available_tables_for_report') }}</span>
            <div class="settings-db-tables-list">
              <div
                v-for="table in warehouse_user_settings[warehouse_tables_setting]"
                :key="table"
                class="settings-db-table-item"
              >
                <span>{{ table }}</span>
                <q-icon
                  name="content_copy"
                  size="xs"
                  color="primary"
                  class="cursor-pointer"
                  :disable="loading"
                  @click="copyData(table)"
                >
                  <q-tooltip>{{ $t('copy') }}</q-tooltip>
                </q-icon>
              </div>
            </div>
          </div>
        </div>
      </template>
    </template>
  </div>
</template>
  
  <script lang="ts">
import { notify } from 'src/components/notifications/notify';
  import { copyToClipboard } from 'quasar';
  import { storeToRefs } from 'pinia';
    import { defineComponent, ref } from 'vue';
  import { useSettingStore  } from 'src/store/main';
  import {
    CONSTANTS,
    grouping_dashboard_setting,
    grouping_purchase_order_setting,
    warehouse_reporting_engine_setting,
    warehouse_username_setting,
    warehouse_password_setting,
    warehouse_host_setting,
    warehouse_port_setting,
    warehouse_database_setting,
    warehouse_tables_setting,
    db_direct_access_setting,
    db_access_username_setting,
    db_access_password_setting,
    db_access_host_setting,
    db_access_port_setting,
    db_access_database_setting,
    db_access_tables_setting
  } from 'src/constants';
  import { ApiExceptions } from 'src/exceptions/index';
  import type { dynamicObj } from 'src/pages/assets';
  import { userApiService } from 'src/services';
  import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
export default defineComponent({
    el: '#app',
        components: { subscriptionDialog },
    data() {
      return {
        CONSTANTS,
        grouping_dashboard_setting,
        show_clickhouse_popup: false,
        warehouse_reporting_engine_setting,
        warehouse_username_setting,
        warehouse_password_setting,
        warehouse_host_setting,
        warehouse_port_setting,
        warehouse_database_setting,
        warehouse_tables_setting,
        db_direct_access_setting,
        db_access_username_setting,
        db_access_password_setting,
        db_access_host_setting,
        db_access_port_setting,
        db_access_tables_setting,
        db_access_database_setting,
        supplier_statistics_setting: CONSTANTS.supplier_statistics_setting,
        grouping_purchase_order_setting,
      };
    },
    watch: {
      loading_settings: {
        handler: function (newVal, oldVal) {
          // data loading is done and value never set
          if (newVal == true && oldVal == false) {
            return;
          }
          this.initView();
        },
      },
    },
    mounted: function () {
      this.initView();
    },
    setup () {
      const settings_store = useSettingStore();
      const { user_settings, loading_settings } = storeToRefs(settings_store);
      const { updateSetting, updateDashboardGroupingSetting, updateReportingEngineSetting, updateDBDirectAccessSetting, updateGroupingPurchaseOrderSetting } = settings_store;
  
      return {
        dashboard_grouping_loading: ref(false),
        user_settings,
        loading_settings,
        loading: ref(false),
        updateSetting,
        updateDashboardGroupingSetting,
        updateReportingEngineSetting,
        updateDBDirectAccessSetting,
        updateGroupingPurchaseOrderSetting,
        warehouse_user_settings: ref({} as dynamicObj),
        db_direct_access_settings: ref({} as dynamicObj),
        db_direct_access_settings_loading: ref(false)
      }
    },
  methods: {
    initView() {
      if (this.user_settings[this.warehouse_reporting_engine_setting]) {
        this.warehouseReportingEngineSetting();
      }

      if (this.user_settings[this.db_direct_access_setting]) {
        this.getDBDirectAccessData();
      }
    },
    async warehouseReportingEngineSetting() {
      try {
        const response =
          await userApiService.getReportingEngineUserPreference();
        if (response.success === false) {
          // DRFS-626: the warehouse reporting engine is off for this org —
          // an expected, neutral state, not an error. Don't log it as an
          // error (it surfaced as console/network noise on every Settings
          // load); just leave the warehouse settings empty.
          logDebug('[Settings] Warehouse reporting engine off', response?.message);
          return;
        }
        this.setWarehouseReportingUserSettings(response.data);
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setWarehouseReportingUserSettings(data: dynamicObj) {
      for (const key in data) {
        if (Object.prototype.hasOwnProperty.call(data, key)) {
          this.warehouse_user_settings[key] = data[key];
        }
      }
    },

    async setDashboardGroupingSetting(key: string, value: any) {
      try {
        this.loading = true;
        this.dashboard_grouping_loading = true;
        await this.updateDashboardGroupingSetting(key, value);

        if (!value && this.user_settings[warehouse_reporting_engine_setting]) {
          this.user_settings[warehouse_reporting_engine_setting] = false;
          await this.setReportingEngineSetting(
            warehouse_reporting_engine_setting,
            false,
          );
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
        this.dashboard_grouping_loading = false;
      }
    },

    async setReportingEngineSetting(key: string, value: any) {
      try {
        this.loading = true;
        if (!value) {
          this.emptyWarehouseReportingUserSettings();
        }

        const response = await this.updateReportingEngineSetting(key, value);
        if (response.success === false) {
          throw response;
        }

        if (value) {
          await this.warehouseReportingEngineSetting();
        }
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setDBDirectAccessSettingData(data: any) {
      this.db_direct_access_settings = {
        [this.db_access_username_setting]: data.DB_USERNAME,
        [this.db_access_password_setting]: data.DB_PASSWORD,
        [this.db_access_host_setting]: data.DB_HOST,
        [this.db_access_port_setting]: data.DB_PORT,
        [this.db_access_database_setting]: data.DB_DATABASE,
        [this.db_access_tables_setting]: data.DB_TABLES,
      };
    },

    async getDBDirectAccessData() {
      try {
        const response = await userApiService.getDBCredentials({
          access_key: db_direct_access_setting,
          enable_user: this.user_settings[db_direct_access_setting],
        });

        if (response.success === false) {
          // DRFS-626: DB direct access not provisioned for this org (the
          // backend returns "User not found" = no credentials record). This
          // is a neutral "not configured" state on passive load, not an
          // error — leave the access fields empty instead of showing a toast.
          logDebug('[Settings] DB direct access not configured', response?.message);
          return;
        }

        this.setDBDirectAccessSettingData(response.data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async setDBDirectAccessSetting(key: string, value: any) {
      try {
        this.emptyDBAccessSettings();
        this.db_direct_access_settings_loading = true;
        const response = await this.updateDBDirectAccessSetting(key, value);
        if (response.success === false) {
          throw response;
        }
        if (value) {
          this.setDBDirectAccessSettingData(response.data);
        }
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.db_direct_access_settings_loading = false;
      }
    },

    emptyWarehouseReportingUserSettings() {
      this.warehouse_user_settings = {
        [this.warehouse_username_setting]: '',
        [this.warehouse_password_setting]: '',
        [this.warehouse_host_setting]: '',
        [this.warehouse_port_setting]: '',
        [this.warehouse_database_setting]: '',
        [this.warehouse_tables_setting]: [],
      };
    },

    emptyDBAccessSettings() {
      this.db_direct_access_settings = {
        [this.db_access_username_setting]: '',
        [this.db_access_password_setting]: '',
        [this.db_access_host_setting]: '',
        [this.db_access_port_setting]: '',
        [this.db_access_database_setting]: '',
        [this.db_access_tables_setting]: [],
      };
    },

    copyData(data: any) {
      if (data.trim().length > 0) {
        copyToClipboard(data).then(() => {
          notify.success(this.$t('copied_successfully'));
        });
      }
    },

    saveClickhouse(value: any) {
      if (value) {
        this.user_settings[this.grouping_dashboard_setting] = false;
        this.show_clickhouse_popup = true;
      } else {
        this.handleClickhouseSubscriptionConfirm(value);
      }
    },

    handleClickhouseSubscriptionConfirm(value: any) {
      this.setDashboardGroupingSetting(this.grouping_dashboard_setting, value);
    },

    async updateSupplierStatisticsSetting(key: string, value: any) {
      try {
        await this.updateSetting(key, value);
        await this.updateGroupingPurchaseOrderSetting(
          this.grouping_purchase_order_setting,
          value,
        );

        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
  },
});
</script>

