<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">

      <!-- No results message -->
      <div v-if="searchQuery && !hasAnyMatch" class="no-results-message text-center q-pa-xl">
        <q-icon name="search_off" size="48px" color="grey-5" />
        <p class="q-mt-md text-grey-6">{{ $t('no_results_found') || 'No matching settings found' }}</p>
      </div>

      <!-- Dashboards Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('dashboards')"
        v-model="expandedSections.dashboards"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('dashboards') }"
        icon="mdi:view-dashboard"
        :title="$t('dashboards')"
        :subtitle="$t('dashboard_configuration')"
        bodyClass=""
      >
        <Dashboards />
      </DocbitsAccordionPanel>

      <!-- AI Dashboard Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('aiDashboard')"
        v-model="expandedSections.aiDashboard"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('aiDashboard') }"
        icon="mdi:head-cog"
        :title="$t('ai_dashboard')"
        :subtitle="$t('ai_analytics_configuration')"
        bodyClass=""
      >
        <AI_Dashboard />
      </DocbitsAccordionPanel>

      <!-- Analytics Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('analytics')"
        v-model="expandedSections.analytics"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('analytics') }"
        icon="mdi:chart-bar"
        :title="$t('analytics')"
        :subtitle="$t('analytics_data_source_configuration')"
        bodyClass=""
      >
        <Analytics />
      </DocbitsAccordionPanel>

      <!-- Database Access Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('dbAccess')"
        v-model="expandedSections.dbAccess"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('dbAccess') }"
        icon="mdi:database"
        :title="$t('database_access')"
        :subtitle="$t('database_connection_settings')"
        bodyClass=""
      >
        <DBAccess />
      </DocbitsAccordionPanel>

    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { useSettingStore } from 'src/store/main';
import { useAccordionSearch, type SectionSearchEntry } from 'src/utils/useAccordionSearch';
import Dashboards from 'src/pages/Settings/Components/Modules/Dashboards.vue';
import AI_Dashboard from 'src/pages/Settings/Components/Modules/AI_Dashboard.vue';
import Analytics from 'src/pages/Settings/Components/Modules/Analytics.vue';
import DBAccess from 'src/pages/Settings/Components/Modules/db-access.vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';

const SEARCH_REGISTRY: Record<string, SectionSearchEntry> = {
  dashboards: {
    titleKeys: ['dashboards', 'dashboard_configuration'],
    childKeys: [
      'advance_shipment_dashboard',
      'invoice_dashboard',
      'fact_sheet_pdf',
      'invoice_document',
      'full_text_search',
      'analytics_dashboard',
    ],
  },
  aiDashboard: {
    titleKeys: ['ai_dashboard', 'ai_analytics_configuration'],
    childKeys: [
      'grouping_dashboard',
      'reporting_engine',
      'supplier_statistics_setting',
    ],
  },
  analytics: {
    titleKeys: ['analytics', 'analytics_data_source_configuration'],
    childKeys: ['analytics'],
  },
  dbAccess: {
    titleKeys: ['database_access', 'database_connection_settings'],
    childKeys: ['db_access'],
  },
};

const SECTION_DEFAULTS: Record<string, boolean> = {
  dashboards: true,
  aiDashboard: false,
  analytics: false,
  dbAccess: false,
};

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  watch: {
    loading_settings: {
      handler: function (newVal) {
        if (newVal) {
          this.showLoading();
        }
      },
    },
    $route() {
      this.scrollToHash();
    },
  },
  components: {
    Dashboards,
    AI_Dashboard,
    Analytics,
    DBAccess,
    DocbitsAccordionPanel,
  },
  mounted: function () {
    this.startSettingsFetch();
    this.scrollToHash();
  },
  methods: {
    scrollToHash() {
      if (this.$route.hash) {
        this.$nextTick(() => {
          setTimeout(() => {
            const element = document.getElementById(
              this.$route.hash.substring(1),
            );
            if (element) {
              element.scrollIntoView({ behavior: 'smooth' });
            }
          }, 100);
        });
      }
    },

    onSearch(searchItem: string) {
      this.handleSearch(searchItem, this.$t);
    },
  },

  setup() {
    const settings_store = useSettingStore();
    const { startSettingsFetch, loading_settings } = settings_store;
    const accordionSearch = useAccordionSearch(SEARCH_REGISTRY, SECTION_DEFAULTS);

    return {
      startSettingsFetch,
      loading_settings,
      ...accordionSearch,
    };
  },
});
</script>

<style lang="scss" scoped>
.section-dimmed {
  opacity: 0.4;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.no-results-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
}
</style>
