<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('advance_shipment_dashboard') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[asn_dashboard_setting]"
          @update:model-value="(val: any) => { updateSetting(asn_dashboard_setting, val); }"
        />
      </div>
    </div>

    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('invoice_dashboard') }}</span>
      </div>
      <div class="settings-toggle-selects" v-if="user_settings[invoice_dashboard_setting]">
        <q-input
          dense
          outlined
          readonly
          class="s-field back-white"
          v-model="invoice_date_formatted"
          :label="$t('invoice_date_limit')"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="invoice_date"
                  :mask="date_pattern"
                  :format="date_pattern"
                  @update:model-value="formatInvoiceLimitDate"
                >
                  <div class="row items-center justify-end">
                    <q-btn
                      :label="$t('save')"
                      @click="toggleSetting(invoice_date_limit, formatDateToUniversal(invoice_date))"
                      color="primary"
                      flat
                      v-close-popup
                    />
                    <q-btn
                      :label="$t('close')"
                      color="primary"
                      flat
                      v-close-popup
                    />
                  </div>
                </q-date>
              </q-popup-proxy>
            </q-icon>
            <q-icon name="info" class="cursor-pointer q-ml-xs" color="primary" size="xs">
              <q-tooltip>{{ $t('invoice_dashboard_filter_date') }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[invoice_dashboard_setting]"
          @update:model-value="updateInvoiceDashboardSetting"
        />
      </div>
    </div>

    <template v-if="user_settings[invoice_dashboard_setting]">
      <div class="settings-toggle-item">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('fact_sheet_pdf') }}</span>
        </div>
        <div class="settings-toggle-actions">
          <f-toggle size="xs"
            v-model="user_settings[fact_sheet_pdf_setting]"
            @update:model-value="(val: any) => { updateDocumentSetting(fact_sheet_pdf_setting, val); }"
          />
        </div>
      </div>

      <div class="settings-toggle-item">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('invoice_document') }}</span>
        </div>
        <div class="settings-toggle-actions">
          <f-toggle size="xs"
            v-model="user_settings[invoice_document_setting]"
            @update:model-value="(val: any) => { updateDocumentSetting(invoice_document_setting, val); }"
          />
        </div>
      </div>
    </template>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('full_text_search') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="settings"
          :settingType="open_search_enabled"
          :appKey="CONSTANTS.opensearch"
          :onConfirm="handleSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[open_search_enabled]"
          @update:model-value="save"
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('analytics_dashboard') }}
          <q-icon
            v-if="!user_settings[grouping_dashboard_setting]"
            name="info"
            size="14px"
            color="warning"
            class="q-ml-xs"
          >
            <q-tooltip>{{ $t('requires_ai_dashboard') }}</q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[analytics_dashboard_setting]"
          :disable="!user_settings[grouping_dashboard_setting]"
          @update:model-value="(val: any) => { toggleSetting(analytics_dashboard_setting, val) }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { copyToClipboard } from 'quasar';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore, useSubscriptionStore } from 'src/store/main';
import {
  grouping_dashboard_setting,
  warehouse_reporting_engine_setting,
  warehouse_username_setting,
  warehouse_password_setting,
  warehouse_host_setting,
  warehouse_port_setting,
  warehouse_database_setting,
  warehouse_tables_setting,
  asn_dashboard_setting,
  invoice_dashboard_setting,
  invoice_document_setting,
  fact_sheet_pdf_setting,
  open_search_enabled,
  invoice_date_limit,
  analytics_dashboard_setting,
  CONSTANTS,
} from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import {
  invoiceDashboardService,
  userApiService,
  fullSearchApiService,
} from 'src/services';
import dateUtils from 'src/utils/date';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import { preferencesService } from 'src/services/preferences/preferencesService';

// Vector preference keys that ride along with OPENSEARCH_ENABLED. When
// the Fulltext module is switched off, these are forced to false too —
// vector embeddings need OpenSearch to function. Mirror of the list in
// src/pages/Settings/Pages/FulltextSettings.vue.
const OPENSEARCH_VECTOR_KEYS = [
  'OPENSEARCH_VECTOR_DOCUMENTS',
  'OPENSEARCH_VECTOR_INVOICES',
  'OPENSEARCH_VECTOR_ATTACHMENTS',
] as const;
export default defineComponent({
  el: '#app',
  mixins: [dateUtils],
  components: {
    subscriptionDialog,
  },
  data() {
    return {
      grouping_dashboard_setting,
      warehouse_reporting_engine_setting,
      warehouse_username_setting,
      warehouse_password_setting,
      warehouse_host_setting,
      warehouse_port_setting,
      warehouse_database_setting,
      warehouse_tables_setting,
      asn_dashboard_setting,
      invoice_dashboard_setting,
      invoice_document_setting,
      fact_sheet_pdf_setting,
      invoice_date_limit,
      open_search_enabled,
      analytics_dashboard_setting,
      CONSTANTS,
      invoice_date: ref(''),
      invoice_date_formatted: ref(''),
      date_pattern: ref(''),
      show_popup: ref(false),
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const {
      updateSetting,
      updateDashboardGroupingSetting,
      updateReportingEngineSetting,
    } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
      updateDashboardGroupingSetting,
      updateReportingEngineSetting,
      warehouse_user_settings: ref({} as dynamicObj),
      invoiceDashboardService,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.grouping_dashboard_setting]) {
        this.user_settings[this.grouping_dashboard_setting] = false;
      }

      if (!this.user_settings[this.warehouse_reporting_engine_setting]) {
        this.user_settings[this.warehouse_reporting_engine_setting] = false;
      }

      if (!this.user_settings[this.asn_dashboard_setting]) {
        this.user_settings[this.asn_dashboard_setting] = false;
      }

      if (!this.user_settings[this.invoice_document_setting]) {
        this.user_settings[this.invoice_document_setting] = false;
      }
      if (!this.user_settings[this.fact_sheet_pdf_setting]) {
        this.user_settings[this.fact_sheet_pdf_setting] = false;
      }
      if (!this.user_settings[this.analytics_dashboard_setting]) {
        this.user_settings[this.analytics_dashboard_setting] = false;
      }

      this.warehouseReportingEngineSetting();

      this.invoice_date = this.user_settings[this.invoice_date_limit] || '';
      this.date_pattern = this.getDatePattern();
      this.formatInvoiceLimitDate();
    },
    async updateDocumentSetting(key: string, value: any) {
      await this.updateSetting(key, value);
      if (!value) {
        return;
      }
      if (key == this.invoice_document_setting) {
        this.user_settings[this.fact_sheet_pdf_setting] = false;
        await this.updateSetting(fact_sheet_pdf_setting, false);
      }
      if (key == this.fact_sheet_pdf_setting) {
        this.user_settings[this.invoice_document_setting] = false;
        await this.updateSetting(invoice_document_setting, false);
      }
      await invoiceDashboardService.resetPreviewPath();
      notify.success(this.$t('save_successfully'));
    },
    async updateInvoiceDashboardSetting(value: any) {
      try {
        await this.updateSetting(invoice_dashboard_setting, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },

    updateDashboardSetting(key: string, value: any) {
      this.updateSetting(key, value);
      if (!value && this.user_settings[this.grouping_dashboard_setting]) {
        this.user_settings[this.grouping_dashboard_setting] = false;
        this.setDashboardGroupingSetting(grouping_dashboard_setting, false);
      }
    },
    async warehouseReportingEngineSetting() {
      try {
        this.emptyWarehouseReportingUserSettings();
        const response =
          await userApiService.getReportingEngineUserPreference();
        if (response.success === false) {
          throw response;
        }
        this.setWarehouseReportingUserSettings(response.data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setWarehouseReportingUserSettings(data: dynamicObj) {
      for (const key in data) {
        if (Object.prototype.hasOwnProperty.call(data, key)) {
          this.warehouse_user_settings[key] = data[key];
        }
      }
    },

    async setDashboardGroupingSetting(key: string, value: any) {
      try {
        this.loading = true;
        await this.updateDashboardGroupingSetting(key, value);

        if (!value && this.user_settings[warehouse_reporting_engine_setting]) {
          this.user_settings[warehouse_reporting_engine_setting] = false;
          this.setReportingEngineSetting(
            warehouse_reporting_engine_setting,
            false,
          );
          this.emptyWarehouseReportingUserSettings();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async setReportingEngineSetting(key: string, value: any) {
      try {
        this.loading = true;
        const response = await this.updateReportingEngineSetting(key, value);

        if (response.success === false) {
          throw response;
        }
        if (!value) {
          this.emptyWarehouseReportingUserSettings();
          return;
        }
        this.warehouseReportingEngineSetting();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    emptyWarehouseReportingUserSettings() {
      this.warehouse_user_settings = {
        [this.warehouse_username_setting]: '',
        [this.warehouse_password_setting]: '',
        [this.warehouse_host_setting]: '',
        [this.warehouse_port_setting]: '',
        [this.warehouse_database_setting]: '',
        [this.warehouse_tables_setting]: [],
      };
    },

    copyData(data: any) {
      if (data.trim().length > 0) {
        copyToClipboard(data).then(() => {
          notify.success(this.$t('copied_successfully'));
        });
      }
    },

    formatInvoiceLimitDate() {
      const date = this.formatDateToUniversal(this.invoice_date);
      this.invoice_date_formatted = this.formatDateAccordingToPreference(
        date,
        true,
      );
    },
    async toggleSetting(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);

        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    cleanupOnhide() {
      this.show_popup = false;
    },
    save(value: any) {
      if (value) {
        // Revert the toggle first
        this.user_settings[this.open_search_enabled] = false;
        this.show_popup = true;
      } else {
        // Disabling - just save directly
        this.handleSubscriptionConfirm(value);
      }
    },
    async handleSubscriptionConfirm(value: any) {
      try {
        this.loading = true;

        if (value) {
          await fullSearchApiService.createOpenSearchIndex();
        } else {
          await fullSearchApiService.deleteOpenSearchIndex();
        }

        await this.updateSetting(open_search_enabled, value);

        if (!value) {
          // Disabling OpenSearch implies disabling Vector — semantic
          // embeddings can't be queried without OpenSearch routing.
          // Asymmetric on purpose: enabling does not auto-enable
          // Vector, that stays an explicit user opt-in. Mirror of the
          // cascade in FulltextSettings.vue's handleSubscriptionConfirm.
          await Promise.allSettled(
            OPENSEARCH_VECTOR_KEYS.map((key) =>
              preferencesService.setOrgPreference(key, false),
            ),
          );
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>